# Scratch environment for a cv daemon/CLI that must never touch the live vault or live databases.
# Usage: . scratch-env.sh <scratch-dir>   (the dir holds vault/ cfg/ state/ cache/ run/)
# >>> shguard modes=source (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'docs/spikes/intake-second-sprint/scratch-env.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  source) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: source; pipe callers set SHGUARD_MODE=pipe)\n' 'scratch-env.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
S=${1:?scratch dir (source from bash: dash passes no arguments to a sourced file)}
export CV_VAULT=$S/vault CV_CONFIG_DIR=$S/cfg CV_STATE_DB=$S/state/state.db CV_SEARCH_DB=$S/state/search.db CV_INDEX_DB=$S/cache/index.db CV_SOCKET=$S/run/daemon.sock XDG_RUNTIME_DIR=$S/run XDG_STATE_HOME=$S/state XDG_CACHE_HOME=$S/cache
unset CV_LINK_WRITE_ROOTS
# the router gateway key is read from the host-env projection into the environment only (never printed)
if [ -r "${LIVE_RT:-/run/user/$(id -u)}/host-env/crucible-vault.env" ]; then set -a; . "${LIVE_RT:-/run/user/$(id -u)}/host-env/crucible-vault.env"; set +a; fi
for v in CV_VAULT CV_CONFIG_DIR CV_STATE_DB CV_SEARCH_DB CV_INDEX_DB CV_SOCKET; do p=; eval "p=\${$v}"; case $p in $S/*) ;; *) echo "REFUSE: $v=$p outside scratch" >&2; return 1;; esac; done
